import Database from 'better-sqlite3';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Data generated by visitors on the running site: page views, retailer clicks,
// and submissions (contact messages, book requests, reader reports).
// Deliberately NOT in the catalog database: that file is a deploy artifact
// regenerated from the pipeline and committed, so mixing live traffic into it
// would mean local test traffic shipping to production and production traffic
// being overwritten on every deploy. This file is never committed.
//
// Locally it lives in backend/data/live/. On Railway the container filesystem
// is wiped on every redeploy, so point PT_LIVE_DB_PATH at a path on an attached
// persistent volume (e.g. /data/live.sqlite) -- without that, counts reset on
// each deploy.
export const LIVE_DB_PATH =
  process.env.PT_LIVE_DB_PATH || path.join(__dirname, '..', '..', 'data', 'live', 'live.sqlite');

fs.mkdirSync(path.dirname(LIVE_DB_PATH), { recursive: true });

const liveDb = new Database(LIVE_DB_PATH);
liveDb.pragma('journal_mode = WAL');
// submissions and retailer_clicks live here too (moved from the catalog database,
// where a redeploy wiped them). book_id is a plain integer: SQLite can't enforce a
// foreign key into another database file.
liveDb.exec(`
CREATE TABLE IF NOT EXISTS page_views (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,        -- 'view' (a site section) | 'book' (a book detail panel)
  view TEXT,                 -- section name when kind = 'view'
  book_id INTEGER,           -- when kind = 'book' (no FK: different database file)
  session_id TEXT NOT NULL,  -- random per-browser-session id; not tied to a person
  viewed_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_page_views_viewed_at ON page_views(viewed_at);
CREATE INDEX IF NOT EXISTS idx_page_views_book_id ON page_views(book_id);

CREATE TABLE IF NOT EXISTS submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL, -- 'contact' | 'review' | 'partnership' | 'correction' | 'book-request'
  -- name/email/message are required for contact/review/partnership/
  -- correction (enforced in routes/submissions.js, not here) but nullable
  -- at the schema level because 'book-request' doesn't collect a name or
  -- message at all, and its email is optional.
  name TEXT,
  email TEXT,
  message TEXT,
  book_title TEXT, -- 'review', 'correction', and 'book-request' (the requested title)
  -- 'book-request' only, both optional — author/ISBN the requester
  -- supplied to help identify the exact edition.
  book_author TEXT,
  isbn TEXT,
  -- 'correction' only — the actual catalog row being flagged. Unlike
  -- book_title (free text a reviewer types), this is set from the book the
  -- reader was actually looking at, so a report can be resolved back to a
  -- specific row without any fuzzy title matching.
  book_id INTEGER,
  -- 'correction' only — coarse category so reports can be triaged by kind
  -- without reading every message first.
  category TEXT,
  -- 'review' only, required, 1-5 — the reviewer's own holistic star
  -- rating. Deliberately separate from the six dimension scores below and
  -- NOT their average: this plays the same role as this app's ★ "real
  -- reader rating" (an independent read) against its ☆ synthesized Quality
  -- Profile score. A reader's overall feeling can genuinely diverge from
  -- the average of the craft dimensions.
  rating INTEGER,
  -- 'review' only, 1-5 each, required together — matches this app's own
  -- six-dimension quality profile rather than a single generic star, since
  -- that's the whole point of the app. Everything else about a review
  -- (subgenre, tropes, spice level, etc.) is derived from our own catalog
  -- data, not asked of the reviewer.
  prose_quality INTEGER,
  romance_quality INTEGER,
  world_building INTEGER,
  pacing_quality INTEGER,
  emotional_payoff INTEGER,
  character_depth INTEGER,
  channel_url TEXT, -- 'partnership' only
  status TEXT NOT NULL DEFAULT 'new', -- 'new' | 'reviewed'
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_submissions_type ON submissions(type);

CREATE TABLE IF NOT EXISTS retailer_clicks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  book_id INTEGER NOT NULL,
  retailer TEXT NOT NULL, -- 'bookshop' | 'amazon' | 'barnes-noble' | 'google-books' | 'audible'
  clicked_at TEXT DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_retailer_clicks_retailer ON retailer_clicks(retailer);
CREATE INDEX IF NOT EXISTS idx_retailer_clicks_book_id ON retailer_clicks(book_id);
`);

export default liveDb;
